#!/usr/bin/env bash
# Rebuild the bundled CMYK press profiles (src/core/colour/icc) from the public
# characterisation data in the ICC registry, with ArgyllCMS (build tool only;
# profiles generated by Argyll are not covered by its licence).
#   apt install argyll   (or brew install argyll-cms)
# Output is released under CC0 1.0 like the RGB profiles.
set -euo pipefail
out="$(cd "$(dirname "$0")/.." && pwd)/src/core/colour/icc"
work="$(mktemp -d)"
cd "$work"
curl -fsSL -o FOGRA39L.txt https://registry.color.org/cmyk-registry/chardata/FOGRA39L.txt
curl -fsSL -o CRPC6.txt https://standards.iso.org/iso/15339/-2/ISO15339-CRPC6.txt
txt2ti3 FOGRA39L.txt fogra39
txt2ti3 CRPC6.txt crpc6
# medium quality A2B/B2A, relative black generation, 330% / 320% total ink, 95% black
colprof -qm -bm -kr -l330 -L95 -A "Quvrelo" \
  -D "Quvrelo Coated FOGRA39 (built from ICC registry FOGRA39L data)" \
  -C "No copyright; CC0 1.0 (built by the Quvrelo project from FOGRA39L characterization data)" fogra39
colprof -qm -bm -kr -l320 -L95 -A "Quvrelo" \
  -D "Quvrelo Premium Coated CRPC6 (GRACoL-style, built from ISO 15339 CRPC6 data)" \
  -C "No copyright; CC0 1.0 (built by the Quvrelo project from ISO 15339-2 CRPC6 characterization data)" crpc6
cp fogra39.icc "$out/QuvreloCoatedFOGRA39.icc"
cp crpc6.icc "$out/QuvreloPremiumCoatedCRPC6.icc"
echo "Profiles written to $out"
